/** The card's layout and pill, from the sources' sample layout (card units). */
export const CARD_CHROME_CSS = "@font-face{font-family:\"Silkscreen\";font-style:normal;font-weight:700;font-display:swap;src:url(\"/fonts/silkscreen-700-latin.woff2\") format(\"woff2\")}\n.pcard{position:relative;width:100%;aspect-ratio:300/112;container-type:inline-size;overflow:visible}\n.pcard-in{position:absolute;inset:0;--pc-u:calc(100cqw / 300);font-family:Archivo,system-ui,sans-serif}\n.pcard-svg{position:absolute;inset:0;display:block;width:100%;height:100%;overflow:visible}\n.pcard-row{position:absolute;left:calc(14 * var(--pc-u));right:calc(14 * var(--pc-u));top:0;bottom:0;display:flex;align-items:center;gap:calc(12 * var(--pc-u))}\n.pcard-av{flex:none;width:calc(58 * var(--pc-u));height:calc(58 * var(--pc-u))}\n.pcard-av>svg{display:block;width:100%;height:100%;overflow:visible}\n.pcard-initial{display:flex;align-items:center;justify-content:center;border-radius:999px;background:var(--pc-badge);color:#0B0B0F;font-weight:800;font-size:calc(28 * var(--pc-u));line-height:1;box-shadow:0 0 0 calc(3 * var(--pc-u)) #06080F}\n.pcard-text{display:flex;min-width:0;flex-direction:column;gap:calc(1 * var(--pc-u))}\n.pcard-name{display:block;box-sizing:border-box;max-width:calc(100% + 36 * var(--pc-u));overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:normal;padding:calc(18 * var(--pc-u));margin:calc(-18 * var(--pc-u));background-origin:content-box !important}\n.pcard-name[data-plain]{font-weight:800;font-size:calc(18 * var(--pc-u));color:#FFFFFF;text-shadow:0 calc(1 * var(--pc-u)) calc(3 * var(--pc-u)) #000}\n.pcard-title{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:700;font-size:calc(12 * var(--pc-u));line-height:normal;color:#E2C07A;text-shadow:0 calc(1 * var(--pc-u)) calc(3 * var(--pc-u)) #000}\n.pcard-pill{display:inline-flex;align-items:center;gap:calc(8 * var(--pc-u));margin-top:calc(3 * var(--pc-u));padding:calc(3 * var(--pc-u)) calc(9 * var(--pc-u)) calc(3 * var(--pc-u)) calc(8 * var(--pc-u));border-radius:999px;background:rgba(6,8,15,0.72);border:1px solid rgba(255,255,255,0.12);align-self:flex-start;white-space:nowrap}\n.pcard-pill-value{font-weight:900;font-size:calc(15 * var(--pc-u));line-height:normal;color:#FFFFFF;font-variant-numeric:tabular-nums;letter-spacing:0.01em}\n.pcard-pill-label{font-weight:800;font-size:calc(13 * var(--pc-u));line-height:1.2;color:#C79BFF}";

/** The items' motion, scoped to the card; every rule stops under prefers-reduced-motion. */
export const CARD_MOTION_CSS = ".pcard .lg-run{stroke-dasharray:16 520;animation:pc-lgRun 3.2s linear infinite}.pcard .lg-run2{animation-delay:-1.1s}.pcard .lg-run3{animation-delay:-2.2s}\n@keyframes pc-lgRun{from{stroke-dashoffset:536}to{stroke-dashoffset:0}}.pcard .lg-glow{animation:pc-lgGlow 2.4s ease-in-out infinite}\n@keyframes pc-lgGlow{0%,100%{opacity:.8}50%{opacity:1}}.pcard .lg-sweep{animation:pc-lgSweep 4.5s ease-in-out infinite}\n@keyframes pc-lgSweep{0%{transform:translateX(-180px)}55%,100%{transform:translateX(440px)}}.pcard .lg-tw{animation:pc-lgTw 2.6s ease-in-out infinite}.pcard .lg-tw2{animation-delay:-.9s}.pcard .lg-tw3{animation-delay:-1.7s}\n@keyframes pc-lgTw{0%,100%{opacity:.25}50%{opacity:1}}.pcard .lg-drift{animation:pc-lgDrift 7s ease-in-out infinite alternate}.pcard .lg-drift2{animation-delay:-2.5s}.pcard .lg-drift3{animation-delay:-5s}\n@keyframes pc-lgDrift{from{transform:translateX(-14px)}to{transform:translateX(14px)}}\n@media (prefers-reduced-motion: reduce){.pcard .lg-run,.pcard .lg-glow,.pcard .lg-sweep,.pcard .lg-tw,.pcard .lg-drift{animation:none}.pcard .lg-run{stroke-dasharray:none;opacity:0}}.pcard .lg-frame{stroke-dasharray:36 780;animation:pc-lgFrame 4.5s linear infinite}\n@keyframes pc-lgFrame{from{stroke-dashoffset:816}to{stroke-dashoffset:0}}\n@media (prefers-reduced-motion: reduce){.pcard .lg-frame{animation:none;opacity:0}}.pcard .lg-iri{animation:pc-lgIri 8s linear infinite}\n@keyframes pc-lgIri{to{filter:hue-rotate(360deg)}}\n@media (prefers-reduced-motion: reduce){.pcard .lg-iri{animation:none}}.pcard .nc-prism{animation:pc-ncFlow 3.5s linear infinite}.pcard .nc-flux{animation:pc-ncFlow 5s linear infinite,pc-ncPulse 2.4s ease-in-out infinite}\n@keyframes pc-ncFlow{to{background-position:200% 0}}\n@keyframes pc-ncPulse{0%,100%{opacity:.88}50%{opacity:1}}\n@media (prefers-reduced-motion: reduce){.pcard .nc-prism,.pcard .nc-flux{animation:none}}.pcard .nc-flux{animation:pc-ncFlicker 3s linear infinite}\n@keyframes pc-ncFlicker{0%,100%{text-shadow:0 0 2px #FFF,0 0 8px #22E4FF,0 0 16px #FF3DCB,0 1px 2px #000}8%{text-shadow:0 0 2px #FFF,0 0 4px #22E4FF,0 0 6px #FF3DCB,0 1px 2px #000;opacity:.85}10%{text-shadow:0 0 3px #FFF,0 0 12px #22E4FF,0 0 22px #FF3DCB,0 1px 2px #000;opacity:1}46%{text-shadow:0 0 2px #FFF,0 0 10px #FF3DCB,0 0 18px #22E4FF,0 1px 2px #000}54%{opacity:.9}56%{opacity:1}}\n@media (prefers-reduced-motion: reduce){.pcard .nc-flux{animation:none}}.pcard .lg-zap{animation:pc-lgZap 1.7s steps(1) infinite}.pcard .lg-zap2{animation-delay:-.6s}.pcard .lg-zap3{animation-delay:-1.1s}\n@keyframes pc-lgZap{0%{opacity:0}12%{opacity:1}18%{opacity:0}46%{opacity:1}50%{opacity:0}78%{opacity:.8}84%{opacity:0}100%{opacity:0}}.pcard .lg-sway{transform-box:view-box;transform-origin:150px -8px;animation:pc-lgSway 4s ease-in-out infinite alternate}\n@keyframes pc-lgSway{from{transform:rotate(-14deg)}to{transform:rotate(14deg)}}\n@media (prefers-reduced-motion: reduce){.pcard .lg-zap{animation:none;opacity:0}.pcard .lg-sway{animation:none}}.pcard .nc-sheen{animation:pc-ncSheen 4.2s linear infinite}\n@keyframes pc-ncSheen{0%{transform:translateX(-110px)}55%,100%{transform:translateX(410px)}}.pcard .nc-node{animation:pc-ncNode 4.2s linear infinite}\n@keyframes pc-ncNode{0%,14%,100%{fill:#06080F;stroke:#FF3DCB}4%{fill:#FFE3F6;stroke:#FFFFFF}}\n@media (prefers-reduced-motion: reduce){.pcard .nc-sheen{animation:none;opacity:0}.pcard .nc-node{animation:none}}";
